                    "hello".into(),
                ),
                LogEntry::llm_prompt(
                    now,
                    1,
                    "d".into(),
                    "m".into(),
                    serde_json::json!([]),
                    serde_json::json!([]),
                ),
                LogEntry::llm_response(
                    now,
                    1,
                    Some("msg_2".into()),
                    Some("echoed: hello".into()),
                    None,
                    None,
