        let mut mgr = SessionManager::new(&dir);
        let session = mgr
            .create("replay-partial", "deepseek-chat", "p")
            .expect("create");
        let now = Utc::now();

        write_log(
            session,
            &[
                // Turn 1: complete
                LogEntry::user_input(now, 1, "hi".into()),
                LogEntry::llm_prompt(
                    now,
                    1,
                    "d".into(),
                    "m".into(),
                    serde_json::json!([]),
                    serde_json::json!([]),
                ),
                LogEntry::llm_response(
                    now,
                    1,
                    Some("m1".into()),
                    Some("hello".into()),
                    None,
                    None,
                    UsageData {
                        input_tokens: 5,
                        output_tokens: 3,
                    },
                ),
                LogEntry::turn_complete(now, 1, "hello".into(), 0),
                // Turn 2: incomplete (crash after user input, no turn_complete)
                LogEntry::user_input(now, 2, "unfinished".into()),
                LogEntry::llm_prompt(
                    now,
                    2,
                    "d".into(),
                    "m".into(),
                    serde_json::json!([]),
