+            input_tokens: 0,
+            output_tokens: 0,
+        };
+        assert_eq!(usage.to_string(), "0 input tokens, 0 output tokens");
+    }
+
+    #[test]
+    fn llm_response_display_uses_usage_display() {
+        let data = LlmResponseData {
+            message_id: None,
+            text: None,
+            reasoning: None,
+            tool_calls: None,
+            usage: UsageData {
+                input_tokens: 12,
+                output_tokens: 34,
+            },
+        };
+        let entry = LogEntry::LlmResponse {
+            ts: "2026-01-01T00:00:00Z".parse().expect("valid timestamp"),
+            turn: 1,
+            data,
+        };
+        assert!(
+            entry.to_string().contains("  Usage: 12 input tokens, 34 output tokens"),
+            "unexpected: {entry}"
+        );
+    }
 }

