    pub fn llm_response(
        ts: DateTime<Utc>,
        turn: u64,
        message_id: Option<String>,
        text: Option<String>,
        reasoning: Option<String>,
        tool_calls: Option<Vec<ToolCallData>>,
        usage: UsageData,
    ) -> Self {
        LogEntry::LlmResponse {
            ts,
            turn,
            data: LlmResponseData {
                message_id,
                text,
                reasoning,
                tool_calls,
                usage,
            },
        }
    }

    pub fn tool_execution(
        ts: DateTime<Utc>,
        turn: u64,
        tool_call_id: String,
        call_id: String,
        name: String,
        arguments: serde_json::Value,
        result: String,
    ) -> Self {
        LogEntry::ToolExecution {
            ts,
